Node.js example: per-route queue with fast reject using p-queue

```js
const PQueue = require('p-queue');
const fastQueue = new PQueue({concurrency: 10});
const slowQueue = new PQueue({concurrency: 5, carryoverConcurrencyCount: false});

async function handleRequest(req, res) {
  const queue = req.path.startsWith('/fast') ? fastQueue : slowQueue;
  if (queue.size + queue.pending >= 100) {
    // fast reject / fallback
    return res.status(503).send({message: 'Service busy, try again or use fallback'});
  }
  try {
    await queue.add(() => process(req));
    res.send({ok:true});
  } catch (err) {
    res.status(500).send({error: 'failed'});
  }
}
```
